#include "stdlib/blas/ext/base/drssors.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/strided/base/stride2offset.h"
#include <stdbool.h>


/**
* Computes the residual sum of squares of two double-precision floating-point strided arrays, ignoring `NaN` values and using an ordinary recursive summation.

*
* @param N            number of indexed elements
* @param X            first input array
* @param strideX      stride length of `X`
* @param Y            second input array
* @param strideY      stride length of `Y`
* @return             output value
*/
double API_SUFFIX( stdlib_strided_drssors )( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const double *Y, const CBLAS_INT strideY ) {
	const CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	const CBLAS_INT oy = stdlib_strided_stride2offset( N, strideY );
	return API_SUFFIX( stdlib_strided_drssors_ndarray )( N, X, strideX, ox, Y, strideY, oy );
}

/**
* Computes the residual sum of squares of two double-precision floating-point strided arrays, ignoring `NaN` values and using an ordinary recursive summation and alternative indexing semantics.

*
* @param N            number of indexed elements
* @param X            first input array
* @param strideX      stride length of `X`
* @param offsetX      starting index for X
* @param Y            second input array
* @param strideY      stride length of `Y`
* @param offsetY      starting index for Y
* @return             output value
*/
double API_SUFFIX( stdlib_strided_drssors_ndarray )( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const double *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	double sum;
	CBLAS_INT ix;
	CBLAS_INT iy;
	double r;
	CBLAS_INT i;

	if ( N <= 0 ) {
		return 0.0;
	}
	ix = offsetX;
	iy = offsetY;
	if ( strideX == 0 && strideY == 0 ) {
		if ( stdlib_base_is_nan( X[ ix ] ) || stdlib_base_is_nan( Y[ iy ] ) ) {
			return 0.0;
		}
		r = X[ ix ] - Y[ iy ];
		return N * r * r;
	}
	// Find the first non-NaN element pair...
	for ( i = 0; i < N; i++ ) {
		if ( stdlib_base_is_nan( X[ ix ] ) == false && stdlib_base_is_nan( Y[ iy ] ) == false ) {
			break;
		}
		ix += strideX;
		iy += strideY;
	}
	if ( i == N ) {
		return 0.0;
	}
	r = X[ ix ] - Y[ iy ];
	sum = r * r;
	ix += strideX;
	iy += strideY;

	for ( i = 1; i < N; i++ ) {
		if ( stdlib_base_is_nan( X[ ix ] ) == false && stdlib_base_is_nan( Y[ iy ] ) == false ) {
			r = X[ ix ] - Y[ iy ];
			sum += r * r;
		}
		ix += strideX;
		iy += strideY;
	}
	return sum;
}
